19	    public class CaptchaService : ICaptchaService
20	    {
21	        private readonly EsignDbContext _context;
22	        private readonly ILogger _logger;
23	        private readonly SupplierOptions _options;
24	        private readonly MsgAPI _msgAPI;
25	        private readonly CaptchaApi _captchaApi;
