29	        // 手机号校验验证码连续失败次数，有效期1小时
30	        private const string PHONE_CAPTCHA_CHK_FAIL_COUNT = "mpur:phone_captcha:chk_fail:count:{0}";
31	        // 手机号校验验证码连续失败最大次数
32	        private const int PHONE_CAPTCHA_CHK_FAIL_MAX_COUNT = 5;
33	        // 手机号校验验证码失败锁定时间, 有效期1小时
34	        private const string PHONE_CAPTCHA_CHK_FAIL_LOCK = "mpur:phone_captcha:chk_fail:lock:{0}";
35	        public CaptchaService(EsignDbContext esignDbContext, ILoggerProvider loggerProvider, 
36	            IOptions<SupplierOptions> optionAccessor, MsgAPI msgAPI, CaptchaApi captchaApi,
37	            IRedisClient redisClient, IHttpContextAccessor httpContextAccessor)
38	        {
39	            if (optionAccessor == null)
40	            {
41	                throw new ArgumentException(null, nameof(optionAccessor));
42	            }
43	
44	            _context = esignDbContext;
45	            _logger = loggerProvider.CreateLogger(nameof(CaptchaService));
46	            _msgAPI = msgAPI;
47	            _options = optionAccessor.Value;
48	            _captchaApi = captchaApi;
49	            _redisClient = redisClient;
50	            _httpContextAccessor = httpContextAccessor;
51	        }
