105	        public async Task<Tuple<ErrCodeEnum, string>> DsmCreateCaptchaAsync(string phone)
106	        {
107	
108	            var createResult = await _captchaApi.Create(phone, _options.Captcha.Source, _options.Captcha.DayMaxGenTimes, DateTime.Now.AddSeconds(_options.Captcha.EffectiveDuration).ToLongUnixTimestamp(), _options.Captcha.MaxGenInterval);
109	
110	            return createResult.Item1
111	                ? Tuple.Create(ErrCodeEnum.Success, createResult.Item2)
112	                : Tuple.Create(ErrCodeEnum.Create_Captcha_300803, createResult.Item2);
113	        }
