116	        /// <inheritdoc/>
117	        public async Task<ErrCodeEnum> VerifyAsync(string code, string phone, bool setUsed = true)
118	        {
119	            _logger.LogInformation($"verify captcha. phone:{phone},code:{code},setUsed:{setUsed},headers:{_httpContextAccessor.HttpContext?.GetHeadersJson()}");
120	
121	            var chkLockKey = string.Format(PHONE_CAPTCHA_CHK_FAIL_LOCK,phone);
122	
123	            var chkLock = await _redisClient.StringGetAsync(chkLockKey);
124	
125	            if (!string.IsNullOrWhiteSpace(chkLock))
126	            {
127	                return ErrCodeEnum.Verify_301002;
128	            }
129	
130	            var validTime = DateTime.Now.ToLongUnixTimestamp();
131	
132	            var ret = await _context.VerificationCodeList.FirstOrDefaultAsync(q =>
133	                q.Target == phone && q.Source == _options.Captcha.Source &&
134	                q.ValidTime > validTime && q.Status == CaptchaStatus.NotUsed);
135	
136	            var chkFailCountKey = string.Format(PHONE_CAPTCHA_CHK_FAIL_COUNT, phone);
137	
138	            if (ret?.Code == code)
139	            {
140	                if (setUsed)
141	                {
142	                    ret.Status = CaptchaStatus.Used;
143	                    _context.Update(ret);
144	                    await _context.SaveChangesAsync();
145	                }
146	
147	                //重置验证失败次数
148	                await _redisClient.StringSetAsync(chkFailCountKey, "0", TimeSpan.FromHours(1));
149	
150	                return ErrCodeEnum.Success;
151	            }
152	
153	
154	            // 增加验证失败次数
155	            var chkFailCount =  await _redisClient.StringIncrementAsync(chkFailCountKey, 1, TimeSpan.FromHours(1));
156	
157	
158	            if (chkFailCount > PHONE_CAPTCHA_CHK_FAIL_MAX_COUNT)
159	            {
160	                await _redisClient.StringSetAsync(chkLockKey,DateTime.Now.ToLongUnixTimestamp().ToString(),TimeSpan.FromHours(1));
161	
162	                return ErrCodeEnum.Verify_301003;
163	            }
164	
165	
166	            if (ret == null)
167	            {
168	                return ErrCodeEnum.Verify_301001;
169	            }
170	
171	
172	            return ErrCodeEnum.CodeVerifyFail;
173	        }
174	
