192	        public Task<bool> DsmSendMsg(string phone, string msg, string sendType = null)
193	        {
194	#if DEBUG
195	            return Task.FromResult(true);
196	#endif
197	            return _msgAPI.DsmSendSmsMsg(phone, msg, sendType == null ? MsgSendType.Captcha.GetDescription() : sendType);
198	        }
