200	        /// <summary>
201	        /// 构建四位数字随机验证码
202	        /// </summary>
203	        /// <returns></returns>
204	        string GenRandomNumber()
205	        {
206	            var random = new Random();
207	            return string.Concat(random.Next(1000, 10000).ToString(), random.Next(10, 100));
208	        }
209	    }
