14	    public class CaptchaService : ICaptchaService
15	    {
16	        private readonly EsignDbContext _context;
17	
18	        private const int DAY_MAX_GEN_TIMES = 30;
19	        private const int MAX_GEN_INTERVAL = 60;
20	        private const string SOURCE = "LINK_SIGN_PORTAL";
21	        private const int EFFECTIVE_DURATION = 900;
22	        private readonly IMapper _mapper;
23	        public CaptchaService(EsignDbContext esignDbContext, IMapper mapper)
24	        {
25	            _context = esignDbContext;
26	            _mapper = mapper;
27	        }
