29	
30	        public async Task<Tuple<ErrCodeEnum, string, string>> CreateCaptchaAsync(string phone, string cid)
31	        {
32	            var startTime = DateTime.Now.Date.ToLongUnixTimestamp();
33	            var endTime = DateTime.Now.AddDays(1).Date.ToLongUnixTimestamp();
34	            var captchaList = await _context.VerificationCodeList.CountAsync(q =>
35	                q.Target == phone &&
36	                q.TargetType == CaptchaTarget.Phone &&
37	                q.SendTime > startTime &&
38	                q.SendTime < endTime &&
39	                q.Source == SOURCE);
40	
41	            if (captchaList > DAY_MAX_GEN_TIMES)
42	            {
43	                return Tuple.Create(ErrCodeEnum.Create_Captcha_300801, string.Empty, string.Empty);
44	            }
45	
46	            var maxCaptchaEntity = await _context.VerificationCodeList
47	                .Where(q => q.Target == phone && q.TargetType == CaptchaTarget.Phone && q.Source == SOURCE)
48	                .OrderByDescending(q => q.SendTime).FirstOrDefaultAsync();
49	
50	            if (maxCaptchaEntity != null && maxCaptchaEntity.SendTime > DateTime.Now.AddSeconds(-MAX_GEN_INTERVAL).ToLongUnixTimestamp())
51	            {
52	                return Tuple.Create(ErrCodeEnum.Create_Captcha_300802, string.Empty, string.Empty);
53	            }
54	
55	            //将未使用状态记录置为作废
56	            await _context.Database.ExecuteSqlInterpolatedAsync($"UPDATE PUB_VERIFICATION_CODES SET STATUS=2 WHERE TARGET={phone} AND STATUS={CaptchaStatus.NotUsed} AND SOURCE={SOURCE}");
57	
58	            var code = GenRandomNumber();
59	
60	            var id = Guid.NewGuid().ToString();
61	            // 将验证码写入表
62	            var verificationCodeEntity = new VerificationCodeEntity
63	            {
64	                Id = id,
65	                SendTime = DateTime.Now.ToLongUnixTimestamp(),
66	                Status = CaptchaStatus.NotUsed,
67	                Source = SOURCE,
68	                Code = code,
69	                Target = phone,
70	                TargetType = CaptchaTarget.Phone,
71	                ValidTime = DateTime.Now.AddSeconds(EFFECTIVE_DURATION).ToLongUnixTimestamp(),
72	                Ex1 = cid
73	            };
74	            await _context.VerificationCodeList.AddAsync(verificationCodeEntity);
75	            var count = await _context.SaveChangesAsync();
76	
77	            return count > 0
78	                ? Tuple.Create(ErrCodeEnum.Success, code, id)
79	                : Tuple.Create(ErrCodeEnum.Create_Captcha_300803, string.Empty, string.Empty);
80	        }
81	
82	        public async Task<Tuple<ErrCodeEnum, VerificationCodeModel>> VerifyAsync(string code, string id)
83	        {
84	
85	            var validTime = DateTime.Now.ToLongUnixTimestamp();
86	
87	            var ret = await _context.VerificationCodeList.FirstOrDefaultAsync(q =>
88	                q.Id == id && q.Source == SOURCE &&
89	                q.ValidTime > validTime && q.Status == CaptchaStatus.NotUsed);
90	
91	            if (ret == null)
92	            {
93	                return Tuple.Create(ErrCodeEnum.Verify_301001, default(VerificationCodeModel));
94	            }
95	
96	#if !DEBUG
97	            if (code != ret.Code)
98	            {
99	                return Tuple.Create(ErrCodeEnum.CodeVerifyFail,default(VerificationCodeModel));
100	            }            
101	#endif
102	            ret.Status = CaptchaStatus.Used;
103	            _context.Update(ret);
104	            await _context.SaveChangesAsync();
105	
106	            return Tuple.Create(ErrCodeEnum.Success, _mapper.Map<VerificationCodeModel>(ret));
107	        }
