109	        /// <summary>
110	        /// 构建六位数字随机验证码
111	        /// </summary>
112	        /// <returns></returns>
113	        string GenRandomNumber()
114	        {
115	            var random = new Random();
116	
117	            return string.Concat(random.Next(1000, 10000).ToString(), random.Next(10, 100));
118	        }
